import java.io.*;

public class Main {
    static boolean vowel(char c) { return c == 'a' || c == 'e' || c == 'i' || c == 'o' || c == 'u'; }

    public static void main(String[] args) throws IOException {
        String s = new String(System.in.readAllBytes(), java.nio.charset.StandardCharsets.UTF_8);
        if (s.endsWith("\n")) s = s.substring(0, s.length() - 1);
        int count = 0, ans = 0;
        // Sliding window of the last three characters.
        for (int i = 0; i < s.length(); i++) {
            if (vowel(s.charAt(i))) count++;
            if (i >= 3 && vowel(s.charAt(i - 3))) count--;
            if (i >= 2 && count == 2) ans++;
        }
        System.out.println(ans);
    }
}

package main

import (
	"fmt"
	"io"
	"os"
	"strings"
)

func vowel(c byte) bool { return strings.IndexByte("aeiou", c) >= 0 }

func main() {
	data, _ := io.ReadAll(os.Stdin)
	s := strings.TrimSuffix(string(data), "\n")
	count, ans := 0, 0
	// Sliding window of the last three characters.
	for i := 0; i < len(s); i++ {
		if vowel(s[i]) {
			count++
		}
		if i >= 3 && vowel(s[i-3]) {
			count--
		}
		if i >= 2 && count == 2 {
			ans++
		}
	}
	fmt.Println(ans)
}
